-- ---------- Code pénal du cabinet : Livret des peines (copie de la feuille Google, sans lien avec Obsidian) ----------
-- Relancer ce fichier remplace toute la table (les retouches faites dans la base sont alors perdues).
drop table if exists cabinet_code_penal;
create table cabinet_code_penal (
  id text primary key,
  article text not null,
  categorie_id text not null,
  titre text not null,
  contenu text,
  amende text,
  detention text,
  procureur boolean not null default false,
  bracelet boolean not null default false,
  autres_sanctions text,
  ordre integer not null default 0,
  created_at timestamptz not null default now()
);
alter table cabinet_code_penal enable row level security;

